export function getSuperDetailedVocabInfo(item) {
  if (!item) return null;
  const word = item.word ? item.word.toLowerCase().trim() : '';

  const defaultPhonetic = item.vietnamesePhonetic || `${item.word} (Đọc chuẩn Anh-Mỹ)`;
  const defaultSyllables = `${(item.word || '').toUpperCase()} ${item.ipa || ''}`;
  const defaultMemoryTip = item.hint || `💡 Từ '${item.word}' có nghĩa là '${item.meaning}'. Bé hãy nghe loa và phát âm lại 3 lần để thuộc làu nhé!`;
  const defaultDailyPhrase = item.example || `I learn the word ${item.word}. (${item.exampleVi || `Bé học từ ${item.word}.`})`;
  const defaultFunFact = `Từ vựng '${item.word}' thuộc nhóm từ cơ bản giúp Minh Anh tự tin phát âm Tiếng Anh chuẩn!`;

  const details = CUSTOM_VOCAB_DETAILS[word] || {};

  return {
    ...item,
    vietnamesePhoneticDisplay: details.vietnamesePhonetic || `Đọc là: "${defaultPhonetic}"`,
    syllableBreakdown: details.syllables || defaultSyllables,
    memoryTip: details.memoryTip || defaultMemoryTip,
    dailyPhrase: details.dailyPhrase || defaultDailyPhrase,
    funFact: details.funFact || defaultFunFact,
    typeLabel: item.type || 'Từ Vựng cốt lõi'
  };
}

const themeStyles = [
  { theme: 'rose', bgHeader: 'bg-rose-600 text-white', borderColor: 'border-rose-500', badgeBg: 'bg-rose-100 text-rose-700', iconColor: '🔴' },
  { theme: 'blue', bgHeader: 'bg-blue-600 text-white', borderColor: 'border-blue-500', badgeBg: 'bg-blue-100 text-blue-700', iconColor: '🔵' },
  { theme: 'amber', bgHeader: 'bg-amber-600 text-white', borderColor: 'border-amber-500', badgeBg: 'bg-amber-100 text-amber-700', iconColor: '🟡' },
  { theme: 'emerald', bgHeader: 'bg-emerald-600 text-white', borderColor: 'border-emerald-500', badgeBg: 'bg-emerald-100 text-emerald-700', iconColor: '🟢' },
  { theme: 'purple', bgHeader: 'bg-purple-600 text-white', borderColor: 'border-purple-500', badgeBg: 'bg-purple-100 text-purple-700', iconColor: '🟣' }
];

const levelNames = {
  L1: 'Khởi Động',
  L2: 'Cơ Bản',
  L3: 'Mở Rộng',
  L4: 'Nâng Cao',
  L5: 'Tiên Phong',
  L6: 'Hội Nhập Quốc Tế'
};

const activeCategories = VOCAB_CATEGORIES.filter(c => c.id !== 'all');

export const ILLUSTRATED_POSTER_PAGES = Array.from({ length: 18 }, (_, pageIdx) => {
  const pageNumber = pageIdx + 1;
  const levelNum = Math.ceil(pageNumber / 3);
  const levelKey = `L${levelNum}`;
  const pageInLevel = ((pageIdx) % 3) + 1;
  
  const pageCats = activeCategories.slice(pageIdx * 5, (pageIdx + 1) * 5);
  
  const sections = pageCats.map((cat, secIdx) => {
    const style = themeStyles[secIdx % themeStyles.length];
    const catWords = VOCABULARY_DATABASE.filter(item => item.category === cat.id).map(item => item.word);
    
    return {
      id: `P${pageNumber}-SEC${secIdx + 1}`,
      categoryId: cat.id,
      title: cat.name,
      theme: style.theme,
      bgHeader: style.bgHeader,
      borderColor: style.borderColor,
      badgeBg: style.badgeBg,
      icon: cat.icon || style.iconColor,
      words: catWords
    };
  });

  return {
    id: pageNumber,
    pageNumber: pageNumber,
    title: `Trang ${pageNumber}: Level ${levelNum} (${levelNames[levelKey]}) - Phần ${pageInLevel}`,
    subtitle: `Bảng minh họa 50 từ vựng cốt lõi theo chủ đề chuẩn (5 Chủ Đề / 50 Từ)`,
    badge: `${levelKey} • 50 Từ Vựng`,
    icon: pageCats[0]?.icon || '🎨',
    level: levelKey,
    description: `Khám phá 50 từ vựng thuộc 5 chủ đề: ${pageCats.map(c => c.name).join(', ')}`,
    sections: sections
  };
});

export default VOCABULARY_DATABASE;
